"use client";

import { useEffect, useState } from "react";
import { Award, Trophy, FileCheck } from "lucide-react";

export default function AboutPage() {
  return (
    <main
      style={{
        padding: "140px 60px",
        color: "white",
        maxWidth: "1100px",
        margin: "0 auto",
      }}
    >
      <Fade>
        <Hero />
      </Fade>

      <Fade delay={0.1}>
        <Experience />
      </Fade>

      <Fade delay={0.2}>
        <Highlights />
      </Fade>

      <Fade delay={0.3}>
        <Skills />
      </Fade>

      <Fade delay={0.4}>
        <Certs />
      </Fade>

      <Fade delay={0.5}>
        <More />
      </Fade>
    </main>
  );
}

/* 🔥 FADE */

function Fade({
  children,
  delay = 0,
}: {
  children: React.ReactNode;
  delay?: number;
}) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setVisible(true), delay * 1000);
    return () => clearTimeout(t);
  }, [delay]);

  return (
    <div
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(20px)",
        transition: "all 0.6s ease",
      }}
    >
      {children}
    </div>
  );
}

/* 🧑‍💻 HERO */

function Hero() {
  return (
    <section
      style={{
        display: "flex",
        gap: "60px",
        alignItems: "center",
        marginBottom: "100px",
        flexWrap: "wrap",
      }}
    >
      <img
        src="/me.jpg"
        alt="Yuna"
        style={{
          width: "160px",
          height: "160px",
          borderRadius: "50%",
          objectFit: "cover",
          border: "1px solid #1e293b",
        }}
      />

      <div style={{ maxWidth: "600px" }}>
        <h1 style={{ fontSize: "44px", marginBottom: "12px" }}>
          Hi, I'm Yuna.
        </h1>

        <p style={{ fontSize: "22px", opacity: 0.9, marginBottom: "12px" }}>
          Software Engineer focused on data, integrations and automation.
        </p>

        <p style={muted}>
          Currently working as a Junior Technology Consultant building
          integration flows, CI/CD pipelines and backend systems.
        </p>

        <p style={{ opacity: 0.5, margin: "20px 0" }}>
          I build systems that transform data into decisions.
        </p>

        <a
          href="/cv.pdf"
          download
          style={primaryBtn}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = "translateY(-2px)";
            e.currentTarget.style.background = "#be123c";
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = "translateY(0)";
            e.currentTarget.style.background = "#e11d48";
          }}
        >
          Download CV
        </a>
      </div>
    </section>
  );
}

