/* 🏆 HIGHLIGHTS */

function Highlights() {
  const items = [
    "CI/CD pipelines with GitHub Actions",
    "Enterprise integration systems",
    "SAP BTP & Cloud Integration",
    "API testing with Postman",
    "Jira & NetSuite workflows",
  ];

  return (
    <section style={{ marginBottom: "80px" }}>
      <h2 style={sectionTitle}>Highlights</h2>

      <div style={grid}>
        {items.map((item) => (
          <div key={item} style={card}>
            {item}
          </div>
        ))}
      </div>
    </section>
  );
}

/* ⚙️ SKILLS */

function Skills() {
  const skills = [
    "Python",
    "FastAPI",
    "React",
    "PostgreSQL",
    "Docker",
    "CI/CD",
    "APIs",
    "Data Integration",
    "SAP BTP",
  ];

  return (
    <section style={{ marginBottom: "80px" }}>
      <h2 style={sectionTitle}>Skills</h2>

      <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
        {skills.map((skill) => (
          <span key={skill} style={tag}>
            {skill}
          </span>
        ))}
      </div>
    </section>
  );
}

/* 🎓 CERTS CON ICONOS */

function Certs() {
  return (
    <section style={{ marginBottom: "80px" }}>
      <h2 style={sectionTitle}>Certifications</h2>

      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div style={certItem}>
          <Award size={18} /> Microsoft Excel Specialist (MOS)
        </div>

        <div style={certItem}>
          <FileCheck size={18} /> SAP BTP Certification
        </div>

        <div style={certItem}>
          <Trophy size={18} /> 3rd place — National Excel Championship
        </div>
      </div>
    </section>
  );
}

/* 🌐 MORE */

function More() {
  return (
    <section>
      <h2 style={sectionTitle}>Discover more about me</h2>

      <div style={{ display: "flex", gap: "15px", flexWrap: "wrap" }}>
        <a
          href="https://github.com/"
          target="_blank"
          style={linkBtn}
          onMouseEnter={hoverFill}
          onMouseLeave={hoverOut}
        >
          GitHub
        </a>

        <a
          href="https://instagram.com/"
          target="_blank"
          style={linkBtn}
          onMouseEnter={hoverFill}
          onMouseLeave={hoverOut}
        >
          Instagram
        </a>

        <a
          href="https://www.linkedin.com/in/yuna-espejo-santana/"
          target="_blank"
          style={linkBtn}
          onMouseEnter={hoverFill}
          onMouseLeave={hoverOut}
        >
          LinkedIn
        </a>
      </div>
    </section>
  );
}

/* 🎨 STYLES */

const sectionTitle = {
  marginBottom: "25px",
  fontSize: "24px",
};

const grid = {
  display: "grid",
  gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))",
  gap: "20px",
};

const card = {
  padding: "20px",
  borderRadius: "12px",
  border: "1px solid #1e293b",
  background: "#020617",
};

const tag = {
  padding: "6px 12px",
  borderRadius: "999px",
  background: "#1e293b",
  fontSize: "14px",
};

const primaryBtn = {
  padding: "10px 18px",
  borderRadius: "8px",
  background: "#e11d48",
  color: "white",
  textDecoration: "none",
  fontWeight: "500",
  transition: "0.2s",
};

const linkBtn: React.CSSProperties = {
  position: "relative",
  overflow: "hidden",
  padding: "10px 16px",
  borderRadius: "8px",
  border: "1px solid #1e293b",
  textDecoration: "none",
  color: "white",
  opacity: 0.85,
  transition: "0.25s",
};



const muted = {
  opacity: 0.65,
  marginTop: "6px",
  fontSize: "14px",
};

const date = {
  fontSize: "12px",
  opacity: 0.4,
  marginTop: "4px",
};

const certItem = {
  display: "flex",
  alignItems: "center",
  gap: "10px",
  opacity: 0.8,
};

/* 🔥 HOVER */

function hoverFill(e: any) {
  e.currentTarget.style.background = "#e11d48";
  e.currentTarget.style.borderColor = "#e11d48";
  e.currentTarget.style.opacity = "1";
}

function hoverOut(e: any) {
  e.currentTarget.style.background = "transparent";
  e.currentTarget.style.borderColor = "#1e293b";
  e.currentTarget.style.opacity = "0.8";
}